import io
from rich.console import Console
from rich.file_proxy import FileProxy

class MockFile(io.TextIOBase):
    def isatty(self):
        return True
    def write(self, s):
        return len(s)

mock_file = MockFile()
console = Console()
proxy = FileProxy(console, mock_file)

print(f"Mock file isatty: {mock_file.isatty()}")
try:
    print(f"Proxy isatty: {proxy.isatty()}")
except Exception as e:
    print(f"Proxy isatty failed: {e}")

if proxy.isatty() == mock_file.isatty():
    print("Success: Proxy delegated isatty")
else:
    print("Failure: Proxy did not delegate isatty")
